#nullable enable // autogenerated

using MVZ2Logic;
using MVZ2Logic.Models;
using MVZ2Logic.Models.Elements;
using PVZEngine.Tools;
using UnityEngine;

namespace MVZ2.GameContent.Models
{
    public class FallenLeavesWindSetter : ModelComponent
    {
        public override void UpdateFrame(float deltaTime)
        {
            base.UpdateFrame(deltaTime);

            var additionalSpeed = Model.GetProperty<float>("WindSpeed") * Global.Level.LawnToTransScale;
            var particleSystem = player.Particles;
            var particleShape = particleSystem.shape;
            var particleVelocityOverLifetime = particleSystem.velocityOverLifetime;

            var xSpeed = particleVelocityOverLifetime.x;
            xSpeed.constantMin = minSpeed + additionalSpeed;
            xSpeed.constantMax = maxSpeed + additionalSpeed;
            particleVelocityOverLifetime.x = xSpeed;

            particleShape.position = Vector3.left * additionalSpeed;
        }
        [SerializeField]
        private ParticlePlayer player = null!;
        [SerializeField]
        private float minSpeed = -1;
        [SerializeField]
        private float maxSpeed = 1;
    }
}
